class _SoftLuxuryMarblePainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final w = size.width;
    final h = size.height;
    final r = Rect.fromLTWH(0, 0, w, h);

    // Clean ivory stone base. The background is intentionally quiet so the UI stays readable.
    final base = Paint()
      ..shader = const LinearGradient(
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
        colors: [Color(0xFFFFFCF5), Color(0xFFF7EEDF), Color(0xFFFFF9EE), Color(0xFFF2E3CE)],
        stops: [0, .34, .68, 1],
      ).createShader(r);
    canvas.drawRect(r, base);

    // Large, soft stone patches: depth without looking like a wallpaper.
    final patches = <_MarblePatch>[
      _MarblePatch(Offset(w * .10, h * .18), w * .34, h * .22, .10),
      _MarblePatch(Offset(w * .86, h * .30), w * .30, h * .28, .07),
      _MarblePatch(Offset(w * .22, h * .67), w * .42, h * .30, .06),
      _MarblePatch(Offset(w * .78, h * .78), w * .38, h * .25, .08),
    ];
    for (final p in patches) {
      final paint = Paint()
        ..shader = RadialGradient(
          colors: [const Color(0xFFC7A77A).withOpacity(p.opacity), Colors.transparent],
        ).createShader(Rect.fromCenter(center: p.center, width: p.width, height: p.height));
      canvas.drawOval(Rect.fromCenter(center: p.center, width: p.width, height: p.height), paint);
    }

    // Organic marble veins. Multiple thin translucent passes create natural stone movement.
    final veinA = Paint()..style = PaintingStyle.stroke..strokeWidth = 1.25..color = const Color(0x2A8E765A);
    final veinB = Paint()..style = PaintingStyle.stroke..strokeWidth = .55..color = const Color(0x208E765A);
    final paths = <Path>[];
    for (int i = -2; i < 5; i++) {
      final x = i * w * .30 + w * .05;
      final p = Path()..moveTo(x, -h * .05);
      p.cubicTo(x + w * .12, h * .15, x - w * .14, h * .27, x + w * .07, h * .40);
      p.cubicTo(x + w * .25, h * .51, x - w * .04, h * .62, x + w * .13, h * .78);
      p.cubicTo(x + w * .24, h * .88, x + w * .02, h * .96, x + w * .10, h * 1.04);
      paths.add(p);
    }
    for (final p in paths) {
      canvas.drawPath(p, veinA);
      final shifted = Path();
      // A nearby hairline follows the main vein instead of forming a rigid parallel stripe.
      final metrics = p.computeMetrics().first;
      final len = metrics.length;
      for (double d = 0; d < len; d += 7) {
        final t = metrics.getTangentForOffset(d);
        if (t == null) continue;
        final normal = Offset(-t.vector.dy, t.vector.dx);
        final n = normal / (normal.distance == 0 ? 1 : normal.distance);
        final pt = t.position + n * 5;
        if (d == 0) shifted.moveTo(pt.dx, pt.dy); else shifted.lineTo(pt.dx, pt.dy);
      }
      canvas.drawPath(shifted, veinB);
    }

    // A very restrained champagne sweep: decorative light, not a palace/arch silhouette.
    final sweep = Paint()
      ..shader = RadialGradient(
        center: const Alignment(-.72, -.78),
        radius: 1.15,
        colors: [const Color(0xFFE5C37C).withOpacity(.18), Colors.transparent],
      ).createShader(r);
    canvas.drawRect(r, sweep);

    // Fine luxury border and four tiny ornamental flourishes.
    final border = Paint()..style = PaintingStyle.stroke..strokeWidth = .8..color = const Color(0x2FC79B52);
    canvas.drawRRect(RRect.fromRectAndRadius(r.deflate(10), const Radius.circular(22)), border);
    final ornament = Paint()..style = PaintingStyle.stroke..strokeWidth = 1.15..color = const Color(0x4AC79B52);
    _flourish(canvas, Offset(24, 112), 1, 1, ornament);
    _flourish(canvas, Offset(w - 24, 112), -1, 1, ornament);
    _flourish(canvas, Offset(24, h - 112), 1, -1, ornament);
    _flourish(canvas, Offset(w - 24, h - 112), -1, -1, ornament);

    // Extremely subtle champagne dust gives the stone a premium finish.
    final dots = Paint()..color = const Color(0x35B98D49);
    for (int i = 0; i < 18; i++) {
      final x = w * ((i * 37) % 97) / 97;
      final y = h * ((i * 61 + 13) % 91) / 91;
      canvas.drawCircle(Offset(x, y), i.isEven ? 1.0 : .65, dots);
    }
  }

  void _flourish(Canvas canvas, Offset o, double sx, double sy, Paint paint) {
    final p = Path()
      ..moveTo(o.dx, o.dy)
      ..cubicTo(o.dx + 14 * sx, o.dy, o.dx + 25 * sx, o.dy + 4 * sy, o.dx + 34 * sx, o.dy + 15 * sy)
      ..cubicTo(o.dx + 23 * sx, o.dy + 9 * sy, o.dx + 15 * sx, o.dy + 20 * sy, o.dx + 10 * sx, o.dy + 31 * sy);
    canvas.drawPath(p, paint);
    canvas.drawCircle(Offset(o.dx + 11 * sx, o.dy + 11 * sy), 1.7, paint);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

class _MarblePatch {
  final Offset center;
  final double width;
  final double height;
  final double opacity;
  const _MarblePatch(this.center, this.width, this.height, this.opacity);
}

class MainShell extends StatefulWidget {
  const MainShell({super.key});

  @override
  State<MainShell> createState() => _MainShellState();
}

class _MainShellState extends State<MainShell> {
  int index = 0;

  @override
  void initState() {
    super.initState();
    _loadCurrentProfile();
  }

  Future<void> _loadCurrentProfile() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    try {
      final snap = await FirebaseFirestore.instance.collection('users').doc(user.uid).get();
      final data = snap.data();
      if (data == null || !mounted) return;
      AppProfileState.cuanId.value = '${data['cuanId'] ?? ''}';
      AppProfileState.name.value = '${data['displayName'] ?? user.displayName ?? 'CUAN USER'}';
      AppProfileState.level.value = (data['level'] is num) ? (data['level'] as num).toInt() : 0;
      AppProfileState.country.value = '${data['country'] ?? 'Indonesia'}';
      AppProfileState.bio.value = '${data['bio'] ?? 'Good Voice • Better Company'}';
      AppProfileState.gender.value = '${data['gender'] ?? 'Laki-laki'}';
      AppProfileState.vip.value = (data['vip'] is num) ? (data['vip'] as num).toInt() : 0;
    } catch (_) {}
  }

  final pages = const [
    HomePage(),
    ChatPage(),
    FamilyPage(),
    ProfilePage(),
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Stack(
        fit: StackFit.expand,
        children: [
          const _LuxuryBackdrop(),
          _RealtimeEconomyBuilder(
            uid: FirebaseAuth.instance.currentUser?.uid ?? '',
            builder: (context, economy) {
              if (economy != null) {
                final coin = economy['coin'] ?? economy['coins'] ?? economy['coinBalance'];
                final diamond = economy['diamond'] ?? economy['diamonds'] ?? economy['diamondBalance'];
                if (coin is num) coinBalance.value = coin.toInt();
                if (diamond is num) diamondBalance.value = diamond.toInt();
              }
              return IndexedStack(index: index, children: pages);
            },
          ),
        ],
      ),
      bottomNavigationBar: _BottomNav(
        index: index,
        onChanged: (v) => setState(() => index = v),
      ),
    );
  }
}

