class _LuxuryCard extends StatelessWidget {
  final Widget child;
  final EdgeInsetsGeometry padding;
  final VoidCallback? onTap;
  final bool dark;
  const _LuxuryCard({
    required this.child,
    this.padding = const EdgeInsets.all(16),
    this.onTap,
    this.dark = false,
  });

  @override
  Widget build(BuildContext context) {
    final radius = BorderRadius.circular(20);
    final card = Container(
      decoration: BoxDecoration(
        borderRadius: radius,
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: dark
              ? const [Color(0xFF4A2A12), Color(0xFF24130B), Color(0xFF4B2B12)]
              : const [Color(0xFFFFF9EA), Color(0xFFF5E2BF), Color(0xFFFFFBF2)],
        ),
        boxShadow: [
          BoxShadow(color: _C.brown.withOpacity(.22), blurRadius: 16, offset: const Offset(0, 6)),
          BoxShadow(color: _C.gold.withOpacity(.18), blurRadius: 10),
        ],
      ),
      child: CustomPaint(
        painter: _OrnateCardPainter(dark: dark),
        child: Padding(padding: padding, child: child),
      ),
    );
    if (onTap == null) return card;
    return Material(color: Colors.transparent, child: InkWell(borderRadius: radius, onTap: onTap, child: card));
  }
}

class _OrnateCardPainter extends CustomPainter {
  final bool dark;
  const _OrnateCardPainter({required this.dark});

  @override
  void paint(Canvas canvas, Size size) {
    final r = RRect.fromRectAndRadius(Offset.zero & size, const Radius.circular(20));
    final outer = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.5
      ..color = _C.gold.withOpacity(.95);
    canvas.drawRRect(r.deflate(1), outer);

    final inner = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = .65
      ..color = _C.gold.withOpacity(.48);
    canvas.drawRRect(r.deflate(6), inner);

    final ornament = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.15
      ..color = _C.gold2.withOpacity(.82);
    final jewel = Paint()..color = const Color(0xFF49A8FF);

    void corner(double x, double y, double sx, double sy) {
      final path = Path()
        ..moveTo(x, y + sy * 20)
        ..quadraticBezierTo(x + sx * 5, y + sy * 8, x + sx * 20, y)
        ..quadraticBezierTo(x + sx * 9, y + sy * 2, x + sx * 4, y + sy * 12);
      canvas.drawPath(path, ornament);
      canvas.drawCircle(Offset(x + sx * 7, y + sy * 7), 2.2, jewel);
    }

    corner(8, 8, 1, 1);
    corner(size.width - 8, 8, -1, 1);
    corner(8, size.height - 8, 1, -1);
    corner(size.width - 8, size.height - 8, -1, -1);

    // Small crown-like flourish at the vertical center of the top/bottom edge.
    final cx = size.width / 2;
    final crown = Path()
      ..moveTo(cx - 16, 5)
      ..lineTo(cx - 10, 10)
      ..lineTo(cx - 3, 5)
      ..lineTo(cx + 3, 10)
      ..lineTo(cx + 10, 5)
      ..lineTo(cx + 16, 5);
    canvas.drawPath(crown, ornament);
    canvas.drawCircle(Offset(cx, 6), 2.4, jewel);

    final bottom = Path()
      ..moveTo(cx - 16, size.height - 5)
      ..lineTo(cx - 10, size.height - 10)
      ..lineTo(cx - 3, size.height - 5)
      ..lineTo(cx + 3, size.height - 10)
      ..lineTo(cx + 10, size.height - 5)
      ..lineTo(cx + 16, size.height - 5);
    canvas.drawPath(bottom, ornament);
    canvas.drawCircle(Offset(cx, size.height - 6), 2.4, jewel);
  }

  @override
  bool shouldRepaint(covariant _OrnateCardPainter oldDelegate) => oldDelegate.dark != dark;
}

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  late final PageController _pageController;
  int _homePage = 1; // 0 = Saya, 1 = Hot, 2 = Discover
  String _mineTab = 'Terakhir';

  final _rooms = const [
    ('Chill Together', 'QueenA', '48.63M Gift', Icons.music_note_rounded),
    ('Night Vibes', 'Raka', '36.20M Gift', Icons.mic_external_on_rounded),
    ('Sultan Lounge', 'Nana', '29.80M Gift', Icons.workspace_premium_rounded),
    ('Fun Talk', 'Dimas', '18.45M Gift', Icons.forum_rounded),
  ];

  @override
  void initState() {
    super.initState();
    _pageController = PageController(initialPage: 1);
  }

  @override
  void dispose() {
    _pageController.dispose();
    super.dispose();
  }

  void _goHomePage(int index) {
    setState(() => _homePage = index);
    _pageController.animateToPage(
      index,
      duration: const Duration(milliseconds: 260),
      curve: Curves.easeOut,
    );
  }

  @override
  Widget build(BuildContext context) {
    final width = MediaQuery.sizeOf(context).width - 40;
    final bannerHeight = width / 3.5; // 700 x 200

    return SafeArea(
      child: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 8, 20, 4),
            child: Row(
              children: [
                const Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text('CUAN PARTY', style: TextStyle(color: _C.text, fontSize: 21, fontWeight: FontWeight.w900)),
                      SizedBox(height: 2),
                      Text('REAL VOICES • REAL PEOPLE', style: TextStyle(color: _C.muted, fontSize: 9, fontWeight: FontWeight.w700, letterSpacing: .6)),
                    ],
                  ),
                ),
                _CircleAction(
                  icon: Icons.search_rounded,
                  onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const UserSearchPage())),
                ),
              ],
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 2, 20, 8),
            child: SizedBox(
              width: double.infinity,
              height: bannerHeight,
              child: _HomeBanner(),
            ),
          ),
          _HomeSwipeTabs(selectedIndex: _homePage, onChanged: _goHomePage),
          const SizedBox(height: 4),
          Expanded(
            child: PageView(
              controller: _pageController,
              onPageChanged: (index) => setState(() => _homePage = index),
              children: [
                ListView(padding: const EdgeInsets.only(bottom: 20), children: [_buildMine()]),
                ListView(padding: const EdgeInsets.only(bottom: 20), children: [_buildHot()]),
                ListView(padding: const EdgeInsets.only(bottom: 20), children: [_buildDiscover()]),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildMine() {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _MainTabBar(tabs: const ['Terakhir', 'Ikuti', 'Gabung'], selected: _mineTab, compact: true, onChanged: (v) => setState(() => _mineTab = v)),
        const SizedBox(height: 10),
        if (_mineTab == 'Terakhir')
          ..._rooms.take(2).map((r) => _RoomHomeCard(room: r))
        else if (_mineTab == 'Ikuti')
          ..._rooms.skip(1).take(2).map((r) => _RoomHomeCard(room: r))
        else
          ..._rooms.skip(2).take(2).map((r) => _RoomHomeCard(room: r)),
      ],
    );
  }

  Widget _buildHot() {
    return Column(
