class LevelProgressStore {
  static final ValueNotifier<int> wealthExp = ValueNotifier<int>(48634920);
  static final ValueNotifier<int> charmExp = ValueNotifier<int>(48282050);
  static final ValueNotifier<int> gameExp = ValueNotifier<int>(628343200);

  static ValueNotifier<int> _notifier(String type) {
    if (type == 'Charm') return charmExp;
    if (type == 'Game') return gameExp;
    return wealthExp;
  }

  static int exp(String type) => _notifier(type).value;

  static void add(String type, int amount) {
    if (amount <= 0) return;
    final notifier = _notifier(type);
    notifier.value += amount;
  }

  static int level(String type) {
    final value = exp(type);
    if (type == 'Game') {
      if (value >= 828343200) {
        return math.min(120, 7 + ((value - 828343200) ~/ 100000000));
      }
      return 6;
    }
    if (value >= 50000000) {
      return math.min(120, 7 + ((value - 50000000) ~/ 25000000));
    }
    return 6;
  }

  static int nextTarget(String type) {
    final lv = level(type);
    if (type == 'Game') {
      if (lv <= 6) return 828343200;
      return 828343200 + ((lv - 7) * 100000000);
    }
    if (lv <= 6) return 50000000;
    return 50000000 + ((lv - 7) * 25000000);
  }

  static int previousTarget(String type) {
    final lv = level(type);
    if (type == 'Game') {
      if (lv <= 6) return 0;
      return 828343200 + ((lv - 7) * 100000000);
    }
    if (lv <= 6) return 0;
    return 50000000 + ((lv - 7) * 25000000);
  }
}

