class UserSearchPage extends StatefulWidget {
  const UserSearchPage({super.key});

  @override
  State<UserSearchPage> createState() => _UserSearchPageState();
}

class _UserSearchPageState extends State<UserSearchPage> {
  final _controller = TextEditingController();
  String? _foundId;
  String? _foundName;

  Future<void> _search() async {
    final id = _controller.text.trim();
    if (id.isEmpty) {
      setState(() { _foundId = null; _foundName = null; });
      return;
    }
    try {
      final snap = await FirebaseFirestore.instance
          .collection('users')
          .where('cuanId', isEqualTo: id)
          .limit(1)
          .get();
      if (!mounted) return;
      if (snap.docs.isEmpty) {
        setState(() { _foundId = null; _foundName = null; });
      } else {
        final data = snap.docs.first.data();
        setState(() {
          _foundId = '${data['cuanId'] ?? id}';
          _foundName = '${data['displayName'] ?? 'CUAN USER'}';
        });
      }
    } catch (_) {
      if (!mounted) return;
      setState(() { _foundId = null; _foundName = null; });
      _showMessage(context, 'Pencarian user gagal. Coba lagi.');
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.transparent,
      extendBodyBehindAppBar: true,
      appBar: AppBar(
        backgroundColor: Colors.transparent,
        elevation: 0,
        foregroundColor: _C.text,
        title: const Text('Cari ID Pengguna', style: TextStyle(fontWeight: FontWeight.w900)),
      ),
      body: Stack(
        fit: StackFit.expand,
        children: [
          const _LuxuryBackdrop(),
          SafeArea(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(20, 74, 20, 20),
              children: [
          TextField(
            controller: _controller,
            keyboardType: TextInputType.number,
            textInputAction: TextInputAction.search,
            onSubmitted: (_) => _search(),
            decoration: InputDecoration(
              hintText: 'Masukkan ID pengguna',
              prefixIcon: const Icon(Icons.search_rounded, color: _C.gold),
              suffixIcon: IconButton(onPressed: _search, icon: const Icon(Icons.arrow_forward_rounded)),
              filled: true,
              fillColor: _C.surface,
              border: OutlineInputBorder(borderRadius: BorderRadius.circular(18), borderSide: BorderSide(color: _C.line)),
              enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(18), borderSide: BorderSide(color: _C.line)),
            ),
          ),
          const SizedBox(height: 18),
          if (_foundId == null && _controller.text.isNotEmpty)
            const _LuxuryCard(child: Padding(
              padding: EdgeInsets.all(16),
              child: Text('User tidak ditemukan.', style: TextStyle(color: _C.muted)),
            )),
          if (_foundId != null)
            _LuxuryCard(
              onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => PrivateChatPage(userName: _foundName ?? 'CUAN USER', userId: _foundId ?? ''))),
              padding: const EdgeInsets.all(16),
              child: Row(
                children: [
                  const CircleAvatar(radius: 28, backgroundColor: _C.gold2, child: Icon(Icons.person, color: _C.brown)),
                  const SizedBox(width: 12),
                  Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Text(_foundName ?? 'CUAN USER', style: const TextStyle(color: _C.text, fontWeight: FontWeight.w900, fontSize: 16)),
                    const SizedBox(height: 4),
                    Text('ID: ' + (_foundId ?? ''), style: const TextStyle(color: _C.muted)),
                  ])),
                  const Icon(Icons.chat_bubble_outline_rounded, color: _C.gold),
                ],
              ),
            ),
          const SizedBox(height: 16),
              const Text('Gunakan ID pengguna untuk membuka profil chat.', style: TextStyle(color: _C.muted, fontSize: 12)),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

